import React from "react";
import "../Styles/Home.css";
import { Link, useNavigate } from "react-router-dom";

const Home = () => {
  const navigate = useNavigate();

  // 🔹 نتحقق من حالة المستخدم
  const role = localStorage.getItem("role");

  const handleGetStarted = () => {
    if (role === "student") {
      navigate("/user-profile");
    } else if (role === "company") {
      navigate("/company-profile");
    } else {
      navigate("/user-register"); // لو ما سجل دخول
    }
  };

  return (
    <div className="home">
      {/* Main Hero Section */}
      <section className="hero">
        <h1 className="hero-title">
          Unlock Your Potential. <span className="accent">Power</span>
        </h1>

        <h1 className="hero-title">
          <span className="accent">UTAS Businesses.</span>
        </h1>

        <p className="hero-text">
          Connect ambitious students with Dhofar companies and ministries for
          flexible, part-time work. Training options are available for
          newcomers.
        </p>

        <button className="hero-btn" onClick={handleGetStarted}>
          Get Start
        </button>
      </section>
    </div>
  );
};

export default Home;
